<script>document.addEventListener('click',function(e){const action=e.target.closest('.customer-popover-menu a[href^="#"]');if(action){action.closest('[popover]')?.hidePopover();return}const b=e.target.closest('[popovertarget^="guarantor-actions-"]');if(!b)return;const m=document.getElementById(b.getAttribute('popovertarget'));const r=b.getBoundingClientRect();m.style.top=Math.max(12,Math.min(r.bottom+8,window.innerHeight-230))+'px';m.style.left=Math.max(12,Math.min(r.right-220,window.innerWidth-232))+'px';},true);</script>
